/// gophertunnel `protocol.DataStoreChangeEntry`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct DataStoreChangeEntry {
    /// The change type. Wire form: `Varuint32`.
    pub change_type: u32,
    /// The update.
    pub update: DataStoreUpdate,
    /// The change.
    pub change: DataStoreChange,
    /// The removal.
    pub removal: DataStoreRemoval,
}

impl Codec for DataStoreChangeEntry {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut x = Self {
            change_type: r.varuint32()?,
            ..Self::default()
        };
        match x.change_type {
            0 => {
                x.update = DataStoreUpdate::decode(r)?;
            }
            1 => {
                x.change.data_store_name = r.string_max(1000)?;
                x.change.property = r.string_max(1000)?;
                x.change.update_count = r.uint32()?;
                decode_marshal_data_store_property_value(r, &mut x.change.new_value)?;
            }
            2 => {
                x.removal.data_store_name = r.string_max(1000)?;
            }
            _ => {
                return Err(Error::UnknownEnum {
                    name: "data store change type",
                    value: i64::from(x.change_type),
                });
            }
        }
        Ok(x)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.varuint32(self.change_type);
        match self.change_type {
            0 => {
                self.update.encode(w)?;
            }
            1 => {
                w.string_max(&self.change.data_store_name, 1000)?;
                w.string_max(&self.change.property, 1000)?;
                w.uint32(self.change.update_count);
                encode_marshal_data_store_property_value(w, &self.change.new_value)?;
            }
            2 => {
                w.string_max(&self.removal.data_store_name, 1000)?;
            }
            _ => {
                return Err(Error::UnknownEnum {
                    name: "data store change type",
                    value: i64::from(self.change_type),
                });
            }
        }
        Ok(())
    }
}

