/// gophertunnel `protocol.MapTrackedObject`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct MapTrackedObject {
    /// The type. Wire form: `Int32`.
    pub r#type: i32,
    /// The entity unique ID. Wire form: a bool, then the value when it is set.
    pub entity_unique_id: Option<i64>,
    /// The block position. Wire form: a bool, then the value when it is set.
    pub block_position: Option<BlockPos>,
}

impl Codec for MapTrackedObject {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let x = Self {
            r#type: r.int32()?,
            entity_unique_id: if r.bool()? {
                Some(r.actor_unique_id()?)
            } else {
                None
            },
            block_position: if r.bool()? {
                Some(r.block_pos()?)
            } else {
                None
            },
        };
        if ((x.r#type) != 0) && ((x.r#type) != 1) {
            return Err(Error::UnknownEnum {
                name: "map tracked object type",
                value: i64::from(x.r#type),
            });
        }
        Ok(x)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.int32(self.r#type);
        w.bool(self.entity_unique_id.is_some());
        if let Some(v) = self.entity_unique_id {
            w.actor_unique_id(v);
        }
        w.bool(self.block_position.is_some());
        if let Some(v) = self.block_position {
            w.block_pos(v);
        }
        if ((self.r#type) != 0) && ((self.r#type) != 1) {
            return Err(Error::UnknownEnum {
                name: "map tracked object type",
                value: i64::from(self.r#type),
            });
        }
        Ok(())
    }
}

