/// gophertunnel `protocol.PlayerListEntry`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct PlayerListEntry {
    /// The action type.
    pub action_type: u8,
    /// The UUID. Wire form: `UUID`.
    pub uuid: Uuid,
    /// The entity unique ID. Wire form: `ActorUniqueID`.
    pub entity_unique_id: i64,
    /// The username. Wire form: `String`.
    pub username: String,
    /// The XUID. Wire form: `String`.
    pub xuid: String,
    /// The platform chat ID. Wire form: `String`.
    pub platform_chat_id: String,
    /// The build platform. Wire form: `Int32`.
    pub build_platform: i32,
    /// The skin.
    pub skin: Skin,
    /// The teacher. Wire form: `Bool`.
    pub teacher: bool,
    /// The host. Wire form: `Bool`.
    pub host: bool,
    /// The sub client. Wire form: `Bool`.
    pub sub_client: bool,
    /// The player colour. Wire form: `BEARGB`.
    pub player_colour: Rgba,
}

impl Codec for PlayerListEntry {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut x = Self::default();
        decode_player_list_action(r, &mut x.action_type)?;
        x.uuid = r.uuid()?;
        if x.action_type == 1 {
            return Ok(x);
        }
        x.entity_unique_id = r.actor_unique_id()?;
        x.username = r.string()?;
        x.xuid = r.string()?;
        x.platform_chat_id = r.string()?;
        x.build_platform = r.int32()?;
        x.skin = Skin::decode(r)?;
        x.teacher = r.bool()?;
        x.host = r.bool()?;
        x.sub_client = r.bool()?;
        x.player_colour = r.be_argb()?;
        Ok(x)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        let mut action_type: u8 = self.action_type;
        action_type = encode_player_list_action(w, action_type)?;
        w.uuid(self.uuid);
        if action_type == 1 {
            return Ok(());
        }
        w.actor_unique_id(self.entity_unique_id);
        w.string(&self.username)?;
        w.string(&self.xuid)?;
        w.string(&self.platform_chat_id)?;
        w.int32(self.build_platform);
        self.skin.encode(w)?;
        w.bool(self.teacher);
        w.bool(self.host);
        w.bool(self.sub_client);
        w.be_argb(self.player_colour);
        Ok(())
    }
}

