/// gophertunnel `protocol.PrimitiveShape`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct PrimitiveShape {
    /// The network ID. Wire form: `Varuint64`.
    pub network_id: u64,
    /// The dimension ID. Wire form: a bool, then the value when it is set.
    pub dimension_id: Option<i32>,
    /// The attached to entity ID. Wire form: a bool, then the value when it is set.
    pub attached_to_entity_id: Option<i64>,
    /// The type. Wire form: a bool, then the value when it is set.
    pub r#type: Option<u8>,
    /// The location. Wire form: a bool, then the value when it is set.
    pub location: Option<[f32; 3]>,
    /// The scale. Wire form: a bool, then the value when it is set.
    pub scale: Option<f32>,
    /// The rotation. Wire form: a bool, then the value when it is set.
    pub rotation: Option<[f32; 3]>,
    /// The total time left. Wire form: a bool, then the value when it is set.
    pub total_time_left: Option<f32>,
    /// The max render distance. Wire form: a bool, then the value when it is set.
    pub max_render_distance: Option<f32>,
    /// The colour. Wire form: a bool, then the value when it is set.
    pub colour: Option<Rgba>,
    /// The extra shape data. Wire form: `ShapeData`.
    pub extra_shape_data: ShapeData,
}

impl Codec for PrimitiveShape {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        Ok(Self {
            network_id: r.varuint64()?,
            r#type: if r.bool()? { Some(r.uint8()?) } else { None },
            location: if r.bool()? { Some(r.vec3()?) } else { None },
            scale: if r.bool()? { Some(r.float32()?) } else { None },
            rotation: if r.bool()? { Some(r.vec3()?) } else { None },
            total_time_left: if r.bool()? { Some(r.float32()?) } else { None },
            max_render_distance: if r.bool()? { Some(r.float32()?) } else { None },
            colour: if r.bool()? { Some(r.be_argb()?) } else { None },
            dimension_id: if r.bool()? { Some(r.varint32()?) } else { None },
            attached_to_entity_id: if r.bool()? {
                Some(r.actor_unique_id()?)
            } else {
                None
            },
            extra_shape_data: r.shape_data()?,
        })
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.varuint64(self.network_id);
        w.bool(self.r#type.is_some());
        if let Some(v) = self.r#type {
            w.uint8(v);
        }
        w.bool(self.location.is_some());
        if let Some(v) = self.location {
            w.vec3(v);
        }
        w.bool(self.scale.is_some());
        if let Some(v) = self.scale {
            w.float32(v);
        }
        w.bool(self.rotation.is_some());
        if let Some(v) = self.rotation {
            w.vec3(v);
        }
        w.bool(self.total_time_left.is_some());
        if let Some(v) = self.total_time_left {
            w.float32(v);
        }
        w.bool(self.max_render_distance.is_some());
        if let Some(v) = self.max_render_distance {
            w.float32(v);
        }
        w.bool(self.colour.is_some());
        if let Some(v) = self.colour {
            w.be_argb(v);
        }
        w.bool(self.dimension_id.is_some());
        if let Some(v) = self.dimension_id {
            w.varint32(v);
        }
        w.bool(self.attached_to_entity_id.is_some());
        if let Some(v) = self.attached_to_entity_id {
            w.actor_unique_id(v);
        }
        w.shape_data(&self.extra_shape_data)?;
        Ok(())
    }
}

