/// gophertunnel `protocol.ScoreboardEntry`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct ScoreboardEntry {
    /// The entry ID. Wire form: `Varint64`.
    pub entry_id: i64,
    /// The objective name. Wire form: `String`.
    pub objective_name: String,
    /// The score. Wire form: `Int32`.
    pub score: i32,
    /// The identity type.
    pub identity_type: u8,
    /// The entity unique ID. Wire form: `ActorUniqueID`.
    pub entity_unique_id: i64,
    /// The display name. Wire form: `String`.
    pub display_name: String,
}

impl Codec for ScoreboardEntry {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut x = Self::default();
        let variant: u32 = r.varuint32()?;
        x.identity_type = go_u32_to_u8(variant);
        let type_names: [&str; 4] = ["remove", "changeplayer", "changeentity", "changefakeplayer"];
        if variant >= 4 {
            return Err(Error::UnknownEnum {
                name: "scoreboard entry variant",
                value: i64::from(variant),
            });
        }
        go_index(&type_names, variant)?;
        r.string()?;
        x.entry_id = r.varint64()?;
        match x.identity_type {
            0 => {
                let objective: Option<String> = if r.bool()? { Some(r.string()?) } else { None };
                x.objective_name = objective.unwrap_or_default();
            }
            1 | 2 => {
                x.objective_name = r.string()?;
                x.score = r.int32()?;
                x.entity_unique_id = r.actor_unique_id()?;
            }
            3 => {
                x.objective_name = r.string()?;
                x.score = r.int32()?;
                x.display_name = r.string()?;
            }
            _ => {}
        }
        Ok(x)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        let mut identity_type: u8 = self.identity_type;
        let variant: u32 = u32::from(identity_type);
        w.varuint32(variant);
        identity_type = go_u32_to_u8(variant);
        let type_names: [&str; 4] = ["remove", "changeplayer", "changeentity", "changefakeplayer"];
        if variant >= 4 {
            return Err(Error::UnknownEnum {
                name: "scoreboard entry variant",
                value: i64::from(variant),
            });
        }
        let type_name: &str = go_index(&type_names, variant)?;
        w.string(type_name)?;
        w.varint64(self.entry_id);
        match identity_type {
            0 => {
                let mut objective: Option<&str> = None;
                if !self.objective_name.is_empty() {
                    objective = Some(self.objective_name.as_str());
                }
                w.bool(objective.is_some());
                if let Some(v) = objective {
                    w.string(v)?;
                }
            }
            1 | 2 => {
                w.string(&self.objective_name)?;
                w.int32(self.score);
                w.actor_unique_id(self.entity_unique_id);
            }
            3 => {
                w.string(&self.objective_name)?;
                w.int32(self.score);
                w.string(&self.display_name)?;
            }
            _ => {}
        }
        Ok(())
    }
}

