/// gophertunnel `protocol.StackResponseSlotInfo`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct StackResponseSlotInfo {
    /// The slot. Wire form: `Uint8`.
    pub slot: u8,
    /// The hotbar slot. Wire form: `Uint8`.
    pub hotbar_slot: u8,
    /// The count. Wire form: `Uint8`.
    pub count: u8,
    /// The stack network ID.
    pub stack_network_id: i32,
    /// The custom name. Wire form: `String`.
    pub custom_name: String,
    /// The filtered custom name. Wire form: a bool, then the value when it is set.
    pub filtered_custom_name: Option<String>,
    /// The durability correction. Wire form: `Varint32`.
    pub durability_correction: i32,
}

impl Codec for StackResponseSlotInfo {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        let mut x = Self {
            slot: r.uint8()?,
            hotbar_slot: r.uint8()?,
            count: r.uint8()?,
            ..Self::default()
        };
        let stack_network_id: Option<i32> = if r.bool()? { Some(r.varint32()?) } else { None };
        if let Some(value) = stack_network_id {
            x.stack_network_id = value;
        }
        x.custom_name = r.string()?;
        x.filtered_custom_name = if r.bool()? { Some(r.string()?) } else { None };
        x.durability_correction = r.varint32()?;
        if (x.durability_correction < (-32768)) || (x.durability_correction > 32767) {
            return Err(Error::InvalidValue {
                field: "durability correction",
                reason: "must fit in an int16",
            });
        }
        Ok(x)
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        w.uint8(self.slot);
        w.uint8(self.hotbar_slot);
        w.uint8(self.count);
        let mut stack_network_id: Option<i32> = None;
        if self.stack_network_id > 0 {
            stack_network_id = Some(self.stack_network_id);
        }
        w.bool(stack_network_id.is_some());
        if let Some(v) = stack_network_id {
            w.varint32(v);
        }
        w.string(&self.custom_name)?;
        w.bool(self.filtered_custom_name.is_some());
        if let Some(v) = &self.filtered_custom_name {
            w.string(v)?;
        }
        w.varint32(self.durability_correction);
        if (self.durability_correction < (-32768)) || (self.durability_correction > 32767) {
            return Err(Error::InvalidValue {
                field: "durability correction",
                reason: "must fit in an int16",
            });
        }
        Ok(())
    }
}

