/// gophertunnel `protocol.SubChunkEntry`.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct SubChunkEntry {
    /// The offset.
    pub offset: SubChunkOffset,
    /// The result. Wire form: `Uint8`.
    pub result: u8,
    /// The raw payload. Wire form: a bool, then the value when it is set.
    pub raw_payload: Option<Vec<u8>>,
    /// The height map type. Wire form: `Uint8`.
    pub height_map_type: u8,
    /// The height map data. Wire form: a bool, then the value when it is set.
    pub height_map_data: Option<HeightMap>,
    /// The render height map type. Wire form: `Uint8`.
    pub render_height_map_type: u8,
    /// The render height map data. Wire form: a bool, then the value when it is set.
    pub render_height_map_data: Option<HeightMap>,
    /// The blob hash. Wire form: a bool, then the value when it is set.
    pub blob_hash: Option<u64>,
}

impl Codec for SubChunkEntry {
    fn decode(r: &mut Reader<'_>) -> Result<Self> {
        Ok(Self {
            offset: SubChunkOffset::decode(r)?,
            result: r.uint8()?,
            raw_payload: if r.bool()? {
                Some(r.byte_slice()?)
            } else {
                None
            },
            height_map_type: r.uint8()?,
            height_map_data: if r.bool()? {
                Some(HeightMap::decode(r)?)
            } else {
                None
            },
            render_height_map_type: r.uint8()?,
            render_height_map_data: if r.bool()? {
                Some(HeightMap::decode(r)?)
            } else {
                None
            },
            blob_hash: if r.bool()? { Some(r.uint64()?) } else { None },
        })
    }

    fn encode(&self, w: &mut Writer) -> Result<()> {
        self.offset.encode(w)?;
        w.uint8(self.result);
        w.bool(self.raw_payload.is_some());
        if let Some(v) = &self.raw_payload {
            w.byte_slice(v)?;
        }
        w.uint8(self.height_map_type);
        w.bool(self.height_map_data.is_some());
        if let Some(v) = self.height_map_data {
            v.encode(w)?;
        }
        w.uint8(self.render_height_map_type);
        w.bool(self.render_height_map_data.is_some());
        if let Some(v) = self.render_height_map_data {
            v.encode(w)?;
        }
        w.bool(self.blob_hash.is_some());
        if let Some(v) = self.blob_hash {
            w.uint64(v);
        }
        Ok(())
    }
}

/// gophertunnel `protocol.SubChunkOffset`.
